VALUES ('doc-09-mitre-attack-p0-9436', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-15T14:07:15.855Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mustang Panda](https://attack.mitre.org/groups/G0129) has leveraged OpenSSH (sshd.exe) to execute commands, transfer files and spread across the environment communicating over SMB port 445.(Citation: Unit42 Chinese VSCode 06 September 2024)", "external_references": [{"description": "Tom Fakterman. (2024, September 6). Chinese APT Abuses VSCode to Target Government in Asia. Retrieved March 24, 2025.", "source_name": "Unit42 Chinese VSCode 06 September 2024", "url": "https://unit42.paloaltonetworks.com/stately-taurus-abuses-vscode-southeast-asian-espionage/"}], "id": "relationship--e67a8b60-ef9c-484b-91b4-0594a7b60eb2", "modified": "2026-07-31T18:47:53.607Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--420ac20b-f2b9-42b8-aa1a-6d4b72895ca4", "spec_version": "2.1", "target_ref": "attack-pattern--4fe28b27-b13c-453e-a386-c2ef362a573b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9436', 0, 85, '09-mitre-attack', 'retrieved', '3A562566CBF7E1F3169992A1B863B5D128875CE29158736B1FA55386FDD7D006', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
