VALUES ('doc-09-mitre-attack-p0-9438', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-14T14:07:39.047Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mustang Panda](https://attack.mitre.org/groups/G0129) has masqueraded malicious executables as legitimate files that download [PlugX](https://attack.mitre.org/software/S0013) malware.(Citation: EclecticIQ Mustang Panda PlugX)(Citation: Sophos PlugX September 2022)", "external_references": [{"description": "EclecticIQ Threat Research Team. (2023, February 2). Mustang Panda APT Group Uses European Commission-Themed Lure to Deliver PlugX Malware. Retrieved September 9, 2025.", "source_name": "EclecticIQ Mustang Panda PlugX", "url": "https://blog.eclecticiq.com/mustang-panda-apt-group-uses-european-commission-themed-lure-to-deliver-plugx-malware"}, {"description": "Secureworks Counter Threat Unit Research Team. (2022, April 27). BRONZE PRESIDENT Targets Russian Speakers with Updated PlugX. Retrieved September 9, 2025.", "source_name": "Sophos PlugX September 2022", "url": "https://www.secureworks.com/blog/bronze-president-targets-russian-speakers-with-updated-plugx"}], "id": "relationship--e8781dcd-4e35-4106-a400-d2f4871b286d", "modified": "2026-07-31T18:47:53.643Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--420ac20b-f2b9-42b8-aa1a-6d4b72895ca4", "spec_version": "2.1", "target_ref": "attack-pattern--208884f1-7b83-4473-ac22-4e1cf6c41471", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9438', 0, 111, '09-mitre-attack', 'retrieved', 'DD9BB2BA0A0E275317EBBD8457FE67EE0138A74994040EFF8C4B851A92BA1EE5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_obje