VALUES ('doc-09-mitre-attack-p0-9440', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-16T19:15:25.792Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mustang Panda](https://attack.mitre.org/groups/G0129) has used DropBox URLs to deliver variants of [PlugX](https://attack.mitre.org/software/S0013).(Citation: Proofpoint TA416 Europe March 2022) [Mustang Panda](https://attack.mitre.org/groups/G0129) has also used Google Drive to host malicious downloads.(Citation: IBM MUSTANG PANDA PUBLOAD CLAIMLOADER JUNE 2025)", "external_references": [{"description": "Golo Muhr, Joshua Chung. (2025, June 23). Hive0154 aka Mustang Panda shifts focus on Tibetan community to deploy Pubload backdoor. Retrieved August 4, 2025.", "source_name": "IBM MUSTANG PANDA PUBLOAD CLAIMLOADER JUNE 2025", "url": "https://www.ibm.com/think/x-force/hive0154-mustang-panda-shifts-focus-tibetan-community-deploy-pubload-backdoor"}, {"description": "Raggi, M. et al. (2022, March 7). The Good, the Bad, and the Web Bug: TA416 Increases Operational Tempo Against European Governments as Conflict in Ukraine Escalates. Retrieved March 16, 2022.", "source_name": "Proofpoint TA416 Europe March 2022", "url": "https://www.proofpoint.com/us/blog/threat-insight/good-bad-and-web-bug-ta416-increases-operational-tempo-against-european"}], "id": "relationship--eac3f09f-fdd0-4bbd-965b-4e22276f4021", "modified": "2026-07-31T18:47:53.681Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--420ac20b-f2b9-42b8-aa1a-6d4b72895ca4", "spec_version": "2.1", "target_ref": "attack-pattern--830c9528-df21-472c-8c14-a036bf17d665", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9440', 0, 139, '09-mitre-attack', 'retrieved', '171B82227E59701E204E5D686241578641CA7E52B93BD51508B307459BBA2E5E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
