VALUES ('doc-09-mitre-attack-p0-9446', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-12T19:26:30.537Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "(Citation: Eset PlugX Korplug Mustang Panda March 2022)(Citation: Anomali MUSTANG PANDA October 2019)(Citation: Secureworks BRONZE PRESIDENT December 2019)(Citation: EclecticIQ Mustang Panda PlugX)(Citation: Avira Mustang Panda January 2020)(Citation: Recorded Future REDDELTA July 2020)(Citation: Crowdstrike MUSTANG PANDA June 2018)(Citation: Proofpoint TA416 Europe March 2022)(Citation: Sophos PlugX September 2022)", "external_references": [{"description": "Alexandre Cote Cyr. (2022, March 23). Mustang Panda’s Hodur: Old tricks, new Korplug variant. Retrieved September 9, 2025.", "source_name": "Eset PlugX Korplug Mustang Panda March 2022", "url": "https://www.welivesecurity.com/2022/03/23/mustang-panda-hodur-old-tricks-new-korplug-variant/"}, {"description": "Anomali Threat Research. (2019, October 7). China-Based APT Mustang Panda Targets Minority Groups, Public and Private Sector Organizations. Retrieved April 12, 2021.", "source_name": "Anomali MUSTANG PANDA October 2019", "url": "https://www.anomali.com/blog/china-based-apt-mustang-panda-targets-minority-groups-public-and-private-sector-organizations"}, {"description": "Counter Threat Unit Research Team. (2019, December 29). BRONZE PRESIDENT Targets NGOs. Retrieved April 13, 2021.", "source_name": "Secureworks BRONZE PRESIDENT December 2019", "url": "https://www.secureworks.com/research/bronze-president-targets-ngos"}, {"description": "EclecticIQ Threat Research Team. (2023, February 2). Mustang Panda APT Group Uses European Commission-Themed Lure to Deliver PlugX Malware. Retrieved September 9, 2025.", "source_name": "EclecticIQ Mustang Panda PlugX", "url": "https://blog.eclecticiq.com/mustang-panda-apt-group-uses-european-commission-themed-lure-to-deliver-plugx-malware"}, {"description": "Hamzeloofard, S. (2020, January 31). New wave of PlugX targets Hong Kong | Avira Blog. Retrieved April 13, 2021.", "source_name": "Avira Mustang Panda January 2020", "url": "https://www.avira.com/en/blog/new-wave-of-plugx-targets-hong-kong"}, {"description": "Insikt Group. (2020, July 28). CHINESE STATE-SPONSORED GROUP ‘REDDELTA’ TARGETS THE VATICAN AND CATHOLIC ORGANIZATIONS. Retrieved April 13, 2021.", "source_name": "Recorded Future REDDELTA July 2020", "url": "https://go.recordedfuture.com/hubfs/reports/cta-2020-0728.pdf"}, {"description": "Meyers, A. (2018, June 15). Meet CrowdStrike’s Adversary of the Month for June: MUSTANG PANDA. Retrieved April 12, 2021.", "source_name": "Crowdstrike MUSTANG PANDA June 2018", "url": "https://www.crowdstrike.com/blog/meet-crowdstrikes-adversary-of-the-month-for-june-mustang-panda/"}, {"description": "Raggi, M. et al. (2022, March 7). The Good, the Bad, and the Web Bug: TA416 Increases Operational Tempo Against European Governments as Conflict in Ukraine Escalates. Retrieved March 16, 2022.", "source_name": "Proofpoint TA416 Europe March 2022", "url": "https://www.proofpoint.com/us/blog/threat-insight/good-bad-and-web-bug-ta416-increases-operational-tempo-against-european"}, {"description": "Secureworks Counter Threat Unit Research Team. (2022, April 27). BRONZE PRESIDENT Targets Russian Speakers with Updated PlugX. Retrieved September 9, 2025.", "source_name": "Sophos PlugX September 2022", "url": "https://www.secureworks.com/blog/bronze-president-targets-russian-speakers-with-updated-plugx"}], "id": "relationship--fc7c27b4-e18f-486a-b7f8-9eb61eec23f2", "modified": "2026-07-31T18:47:53.831Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--420ac20b-f2b9-42b8-aa1a-6d4b72895ca4", "spec_version": "2.1", "target_ref": "malware--64fa0de0-6240-41f4-8638-f4ca7ed528fd", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x