VALUES ('doc-09-mitre-attack-p0-9450', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-25T23:13:44.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ZIRCONIUM](https://attack.mitre.org/groups/G0128) has utilized an ORB (operational relay box) network – consisting compromised devices such as small office and home office (SOHO) routers, IoT devices, and leased virtual private servers (VPS) – to obfuscate the origin of C2 traffic.(Citation: ORB Mandiant) ", "external_references": [{"description": "Raggi, Michael. (2024, May 22). IOC Extinction? China-Nexus Cyber Espionage Actors Use ORB Networks to Raise Cost on Defenders. Retrieved July 8, 2024.", "source_name": "ORB Mandiant", "url": "https://cloud.google.com/blog/topics/threat-intelligence/china-nexus-espionage-orb-networks"}], "id": "relationship--170931d2-d803-4cc8-8e05-4218fcbb5f80", "modified": "2026-07-31T18:47:52.046Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--4283ae19-69c7-4347-a35e-b56f08eb660b", "spec_version": "2.1", "target_ref": "attack-pattern--eb897572-8979-4242-a089-56f294f4c91d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9450', 0, 100, '09-mitre-attack', 'retrieved', '1553BBAE47C70FF9DE3FB0BAC3BA948D9D75B63C99A10EAFA6DCEEB464A9F52C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
