VALUES ('doc-09-mitre-attack-p0-9453', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-07-08T17:52:01.895Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ZIRCONIUM](https://attack.mitre.org/groups/G0128) has compromised network devices such as small office and home office (SOHO) routers and IoT devices for ORB (operational relay box) [Proxy](https://attack.mitre.org/techniques/T1090) networks.(Citation: ORB APT31)(Citation: ORB Mandiant) ", "external_references": [{"description": "Cimpanu, Catalin. (2021, July 20). Chinese hacking group APT31 uses mesh of home routers to disguise attacks. Retrieved July 8, 2024.", "source_name": "ORB APT31", "url": "https://therecord.media/chinese-hacking-group-apt31-uses-mesh-of-home-routers-to-disguise-attacks"}, {"description": "Raggi, Michael. (2024, May 22). IOC Extinction? China-Nexus Cyber Espionage Actors Use ORB Networks to Raise Cost on Defenders. Retrieved July 8, 2024.", "source_name": "ORB Mandiant", "url": "https://cloud.google.com/blog/topics/threat-intelligence/china-nexus-espionage-orb-networks"}], "id": "relationship--22e22e70-7544-40b9-838a-e06b560f51a7", "modified": "2026-07-31T18:47:52.126Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--4283ae19-69c7-4347-a35e-b56f08eb660b", "spec_version": "2.1", "target_ref": "attack-pattern--149b477f-f364-4824-b1b5-aa1d56115869", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9453', 0, 115, '09-mitre-attack', 'retrieved', '4748E4CD9731732D5D610BE525F0D56B528DC2A695B7C1DD122C7A775BE17CA1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
