VALUES ('doc-09-mitre-attack-p0-9475', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-25T13:55:30.701Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ZIRCONIUM](https://attack.mitre.org/groups/G0128) has used Dropbox for C2 allowing upload and download of files as well as execution of arbitrary commands.(Citation: Google Election Threats October 2020)(Citation: Zscaler APT31 Covid-19 October 2020)", "external_references": [{"description": "Huntley, S. (2020, October 16). How We''re Tackling Evolving Online Threats. Retrieved March 24, 2021.", "source_name": "Google Election Threats October 2020", "url": "https://blog.google/threat-analysis-group/how-were-tackling-evolving-online-threats/"}, {"description": "Singh, S. and Antil, S. (2020, October 27). APT-31 Leverages COVID-19 Vaccine Theme and Abuses Legitimate Online Services. Retrieved March 24, 2021.", "source_name": "Zscaler APT31 Covid-19 October 2020", "url": "https://www.zscaler.com/blogs/security-research/apt-31-leverages-covid-19-vaccine-theme-and-abuses-legitimate-online"}], "id": "relationship--f309c2e1-779f-4ff4-b6b7-579aca478239", "modified": "2026-07-31T18:47:52.560Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--4283ae19-69c7-4347-a35e-b56f08eb660b", "spec_version": "2.1", "target_ref": "attack-pattern--be055942-6e63-49d7-9fa1-9cb7d8a8f3f4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9475', 0, 114, '09-mitre-attack', 'retrieved', 'EC2472C52FD47CDCDD0AD97AC8E2C06F36624013F1C037C3E80B83C81F18C1BC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
