VALUES ('doc-09-mitre-attack-p0-9476', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-26T16:17:59.751Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Rocke](https://attack.mitre.org/groups/G0106) exploited Apache Struts, Oracle WebLogic (CVE-2017-10271), and Adobe ColdFusion (CVE-2017-3066) vulnerabilities to deliver malware.(Citation: Talos Rocke August 2018)(Citation: Unit 42 Rocke January 2019)", "external_references": [{"description": "Liebenberg, D.. (2018, August 30). Rocke: The Champion of Monero Miners. Retrieved May 26, 2020.", "source_name": "Talos Rocke August 2018", "url": "https://blog.talosintelligence.com/2018/08/rocke-champion-of-monero-miners.html"}, {"description": "Xingyu, J.. (2019, January 17). Malware Used by Rocke Group Evolves to Evade Detection by Cloud Security Products. Retrieved May 26, 2020.", "source_name": "Unit 42 Rocke January 2019", "url": "https://unit42.paloaltonetworks.com/malware-used-by-rocke-group-evolves-to-evade-detection-by-cloud-security-products/"}], "id": "relationship--06508c23-746d-4894-b414-cff925692bd5", "modified": "2026-07-31T18:47:52.065Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--44102191-3a31-45f8-acbe-34bdb441d5ad", "spec_version": "2.1", "target_ref": "attack-pattern--3f886f2a-874f-4333-b794-aa6075009b1c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9476', 0, 108, '09-mitre-attack', 'retrieved', 'E30D5AE6F97CD9A7D7371FA69164E282E4E88C7D5FE77E36C243103536840BDA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
