VALUES ('doc-09-mitre-attack-p0-9547', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-14T21:15:47.896Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Scattered Spider](https://attack.mitre.org/groups/G1015) has run `SYSTEMD_UNIT_PATH=\"/lib/systemd/\nsystem/teleport.service` to establish persistence for the Teleport remote access tool.(Citation: Mandiant VMware vSphere JUL 2025)", "external_references": [{"description": "Mandiant Incident Response. (2025, July 23). From Help Desk to Hypervisor: Defending Your VMware vSphere Estate from UNC3944. Retrieved October 13, 2025.", "source_name": "Mandiant VMware vSphere JUL 2025", "url": "https://cloud.google.com/blog/topics/threat-intelligence/defending-vsphere-from-unc3944"}], "id": "relationship--85a38210-d648-4bfc-8d44-28c3a08b481a", "modified": "2026-07-31T20:48:34.314Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--44d37b89-a739-4810-9111-0d2617a8939b", "spec_version": "2.1", "target_ref": "attack-pattern--dfefe2ed-4389-4318-8762-f0272b350a1b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9547', 0, 80, '09-mitre-attack', 'retrieved', 'F7C7F0773E5021C9F23AAC3C7B6A330AB6D056FBF238421AC2DECD111C82B178', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
