VALUES ('doc-09-mitre-attack-p0-9555', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-07-13T19:19:23.811Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Scattered Spider](https://attack.mitre.org/groups/G1015) has used multifactor authentication (MFA) fatigue by sending repeated MFA authentication requests to targets.(Citation: CrowdStrike Scattered Spider BYOVD January 2023)(Citation: Check Point Scattered Spider JUL 2025)", "external_references": [{"description": "Check Point Team. (2025, July 7). Exposing Scattered Spider: New Indicators Highlight Growing Threat to Enterprises and Aviation. Retrieved October 13, 2025.", "source_name": "Check Point Scattered Spider JUL 2025", "url": "https://blog.checkpoint.com/research/exposing-scattered-spider-new-indicators-highlight-growing-threat-to-enterprises-and-aviation/"}, {"description": "CrowdStrike. (2023, January 10). SCATTERED SPIDER Exploits Windows Security Deficiencies with Bring-Your-Own-Vulnerable-Driver Tactic in Attempt to Bypass Endpoint Security. Retrieved July 5, 2023.", "source_name": "CrowdStrike Scattered Spider BYOVD January 2023", "url": "https://www.crowdstrike.com/blog/scattered-spider-attempts-to-avoid-detection-with-bring-your-own-vulnerable-driver-tactic/"}], "id": "relationship--a3fef23a-9f22-4d7c-b9f1-3f05372e9d87", "modified": "2026-07-31T20:48:34.374Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--44d37b89-a739-4810-9111-0d2617a8939b", "spec_version": "2.1", "target_ref": "attack-pattern--954a1639-f2d6-407d-aef3-4917622ca493", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9555', 0, 123, '09-mitre-attack', 'retrieved', 'AC98FE4B00331290FD8A67A29E378555BFF23804BAECBE05262C3C