VALUES ('doc-09-mitre-attack-p0-9578', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-14T19:18:28.296Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Scattered Spider](https://attack.mitre.org/groups/G1015) has installed protocol-tunneling tools on VMware vCenter and adversary-controlled VMs, including Teleport.sh, Chisel (configured to communicate with trycloudflare[.]com subdomains), MobaXterm, ngrok, Pinggy, and Teleport.(Citation: CrowdStrike Scattered Spider JUL 2025)(Citation: CISA Scattered Spider Advisory November 2023)", "external_references": [{"description": " Counter Adversary Operations. (2025, July 2). CrowdStrike Services Observes SCATTERED SPIDER Escalate Attacks Across Industries. Retrieved October 13, 2025.", "source_name": "CrowdStrike Scattered Spider JUL 2025", "url": "https://www.crowdstrike.com/en-us/blog/crowdstrike-services-observes-scattered-spider-escalate-attacks/"}, {"description": "CISA. (2023, November 16). Cybersecurity Advisory: Scattered Spider (AA23-320A). Retrieved March 18, 2024.", "source_name": "CISA Scattered Spider Advisory November 2023", "url": "https://www.cisa.gov/news-events/cybersecurity-advisories/aa23-320a"}], "id": "relationship--e9f04e42-2c14-406a-9ddf-ce93f91beab7", "modified": "2026-07-31T20:48:34.561Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--44d37b89-a739-4810-9111-0d2617a8939b", "spec_version": "2.1", "target_ref": "attack-pattern--4fe28b27-b13c-453e-a386-c2ef362a573b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9578', 0, 119, '09-mitre-attack', 'retrieved', '5EF159EFDD35E8FECE3C4BF0B9C8832888C770E42FE4E759619997F3B43663B6', 'v1', '{"source_id": "09-mitre-attack", "version": "retr