VALUES ('doc-09-mitre-attack-p0-9681', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-06-04T19:24:59.821Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[UNC3886](https://attack.mitre.org/groups/G1048) has used Gzip and the Windows command `makecab` to compress files and stolen credentials from victim systems.(Citation: Google Cloud Threat Intelligence ESXi VIBs 2022)(Citation: Google Cloud Mandiant UNC3886 2024)", "external_references": [{"description": " Punsaen Boonyakarn, Shawn Chew, Logeswaran Nadarajan, Mathew Potaczek, Jakub Jozwiak, and Alex Marvi. (2024, June 18). Cloaked and Covert: Uncovering UNC3886 Espionage Operations. Retrieved September 24, 2024.", "source_name": "Google Cloud Mandiant UNC3886 2024", "url": "https://cloud.google.com/blog/topics/threat-intelligence/uncovering-unc3886-espionage-operations"}, {"description": "Alexander Marvi, Jeremy Koppen, Tufail Ahmed, and Jonathan Lepore. (2022, September 29). Bad VIB(E)s Part One: Investigating Novel Malware Persistence Within ESXi Hypervisors. Retrieved March 26, 2025.", "source_name": "Google Cloud Threat Intelligence ESXi VIBs 2022", "url": "https://cloud.google.com/blog/topics/threat-intelligence/esxi-hypervisors-malware-persistence"}], "id": "relationship--9f7800b9-9152-4f4a-a7f7-ad5823b710c3", "modified": "2026-07-31T18:47:53.941Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--461b8e25-8f4a-4ea2-a4a8-e39df7ce6630", "spec_version": "2.1", "target_ref": "attack-pattern--00f90846-cbd1-4fc5-9233-df5c2bf2a662", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9681', 0, 135, '09-mitre-attack', 'retrieved', 'AE11A51DB0153C2FF0A686A4CBCAA11C24BFD6C559923DFE28CC55D11C8F512F', 'v1', '{"s