VALUES ('doc-09-mitre-attack-p0-9685', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-06-05T19:56:30.221Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[UNC3886](https://attack.mitre.org/groups/G1048) has used the publicly available rootkits [REPTILE](https://attack.mitre.org/software/S1219) and [MEDUSA](https://attack.mitre.org/software/S1220).(Citation: Google Cloud Mandiant UNC3886 2024)", "external_references": [{"description": " Punsaen Boonyakarn, Shawn Chew, Logeswaran Nadarajan, Mathew Potaczek, Jakub Jozwiak, and Alex Marvi. (2024, June 18). Cloaked and Covert: Uncovering UNC3886 Espionage Operations. Retrieved September 24, 2024.", "source_name": "Google Cloud Mandiant UNC3886 2024", "url": "https://cloud.google.com/blog/topics/threat-intelligence/uncovering-unc3886-espionage-operations"}], "id": "relationship--a4bc3995-bd65-4a40-b7fc-088dcdddde0a", "modified": "2026-07-31T18:47:54.001Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--461b8e25-8f4a-4ea2-a4a8-e39df7ce6630", "spec_version": "2.1", "target_ref": "attack-pattern--7807d3a4-a885-4639-a786-c1ed41484970", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9685', 0, 82, '09-mitre-attack', 'retrieved', '058885ADB9A1FBA2581A4C3EB5CFF6C6E11951A6E54ACF2072DEA8E7A92A63BC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
