VALUES ('doc-09-mitre-attack-p0-9686', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-05-30T20:33:25.262Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": " [UNC3886](https://attack.mitre.org/groups/G1048) has executed Windows commands on guest virtual machines through `vmtoolsd.exe`.(Citation: Google Cloud Threat Intelligence ESXi VIBs 2022)", "external_references": [{"description": "Alexander Marvi, Jeremy Koppen, Tufail Ahmed, and Jonathan Lepore. (2022, September 29). Bad VIB(E)s Part One: Investigating Novel Malware Persistence Within ESXi Hypervisors. Retrieved March 26, 2025.", "source_name": "Google Cloud Threat Intelligence ESXi VIBs 2022", "url": "https://cloud.google.com/blog/topics/threat-intelligence/esxi-hypervisors-malware-persistence"}], "id": "relationship--a50e8815-a47b-4a6d-9e51-b5fdba686c2c", "modified": "2026-07-31T18:47:54.014Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--461b8e25-8f4a-4ea2-a4a8-e39df7ce6630", "spec_version": "2.1", "target_ref": "attack-pattern--d1fcf083-a721-4223-aedf-bf8960798d62", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9686', 0, 87, '09-mitre-attack', 'retrieved', 'AFB94AFE25B5D435E1E9D30B3D727859AE22D10B981BE2522D0224BB58C1AC7A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
