VALUES ('doc-09-mitre-attack-p0-9687', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-20T20:21:47.334Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[UNC3886](https://attack.mitre.org/groups/G1048) has named a file ‘fgfm’ in an attempt to disguise it as the legitimate service ‘fgfmd’ which facilitates communication between FortiManager and the FortiGate firewall.(Citation: Mandiant Fortinet Zero Day)", "external_references": [{"description": "Marvi, A. et al.. (2023, March 16). Fortinet Zero-Day and Custom Malware Used by Suspected Chinese Actor in Espionage Operation. Retrieved March 22, 2023.", "source_name": "Mandiant Fortinet Zero Day", "url": "https://www.mandiant.com/resources/blog/fortinet-malware-ecosystem"}], "id": "relationship--ab429228-9528-49c6-a986-7999199ab7f7", "modified": "2026-07-31T18:47:54.042Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--461b8e25-8f4a-4ea2-a4a8-e39df7ce6630", "spec_version": "2.1", "target_ref": "attack-pattern--7bdca9d5-d500-4d7d-8c52-5fd47baf4c0c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9687', 0, 92, '09-mitre-attack', 'retrieved', 'B1DC2367F4E3637AE12A42400F7DE6450CD5DFAFAF9F1E69488A95FF099A0BDF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
