VALUES ('doc-09-mitre-attack-p0-9688', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-06-16T19:03:56.574Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[UNC3886](https://attack.mitre.org/groups/G1048) has attempted to bypass digital signature verification checks at startup by adding a command to the startup config `/etc/init.d/localnet` within the rootfs.gz archive of both FortiManager and FortiAnalyzer devices.(Citation: Mandiant Fortinet Zero Day)", "external_references": [{"description": "Marvi, A. et al.. (2023, March 16). Fortinet Zero-Day and Custom Malware Used by Suspected Chinese Actor in Espionage Operation. Retrieved March 22, 2023.", "source_name": "Mandiant Fortinet Zero Day", "url": "https://www.mandiant.com/resources/blog/fortinet-malware-ecosystem"}], "id": "relationship--ae7cff1e-cb46-45f5-8d96-e2448f64cfe2", "modified": "2026-07-31T18:47:54.066Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--461b8e25-8f4a-4ea2-a4a8-e39df7ce6630", "spec_version": "2.1", "target_ref": "attack-pattern--03259939-0b57-482f-8eb5-87c0e0d54334", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9688', 0, 96, '09-mitre-attack', 'retrieved', 'CB7C8FF7A759F31EB26BA37DF3F56B420A2FCC384784244E96A7C884DC24F2DD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
