VALUES ('doc-09-mitre-attack-p0-9727', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-23T02:43:59.389Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Contagious Interview](https://attack.mitre.org/groups/G1052) has utilized VBS scripts to open cmd.exe and run commands to include the go_batch.bat batch file.(Citation: Sekoia ClickFake 2025)", "external_references": [{"description": "Amaury G., Coline Chavane, Felix Aimé and Sekoia TDR. (2025, March 31). From Contagious to ClickFake Interview: Lazarus leveraging the ClickFix tactic. Retrieved April 1, 2025.", "source_name": "Sekoia ClickFake 2025", "url": "https://blog.sekoia.io/clickfake-interview-campaign-by-lazarus/"}], "id": "relationship--54a62885-d76d-44b2-be94-9b677bf472d9", "modified": "2026-07-31T18:47:54.584Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--46599a4a-77ee-4697-9474-2683b6464859", "spec_version": "2.1", "target_ref": "attack-pattern--d1fcf083-a721-4223-aedf-bf8960798d62", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9727', 0, 84, '09-mitre-attack', 'retrieved', '3F6D66E859A93408C14D6996B3AA15E5CAAA87A648BB0EC913157B94700EB68F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
