VALUES ('doc-09-mitre-attack-p0-9735', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-22T22:14:00.747Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Contagious Interview](https://attack.mitre.org/groups/G1052) has established persistence using [InvisibleFerret](https://attack.mitre.org/software/S1245) malware to create file to run the script on Startup via LaunchAgents.(Citation: Zscaler ContagiousInterview BeaverTail InvisibleFerret November 2024) [Contagious Interview](https://attack.mitre.org/groups/G1052) has also utilized a plist file located in `/Library/LaunchAgents` to enable a malicious bash script the ability to persist.(Citation: Sekoia ClickFake 2025)", "external_references": [{"description": "Amaury G., Coline Chavane, Felix Aimé and Sekoia TDR. (2025, March 31). From Contagious to ClickFake Interview: Lazarus leveraging the ClickFix tactic. Retrieved April 1, 2025.", "source_name": "Sekoia ClickFake 2025", "url": "https://blog.sekoia.io/clickfake-interview-campaign-by-lazarus/"}, {"description": "Seongsu Park. (2024, November 4). From Pyongyang to Your Payroll: The Rise of North Korean Remote Workers in the West. Retrieved October 17, 2025.", "source_name": "Zscaler ContagiousInterview BeaverTail InvisibleFerret November 2024", "url": "https://www.zscaler.com/blogs/security-research/pyongyang-your-payroll-rise-north-korean-remote-workers-west"}], "id": "relationship--7596369c-9096-4b91-ab65-574f0bb3d21f", "modified": "2026-07-31T18:47:54.651Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--46599a4a-77ee-4697-9474-2683b6464859", "spec_version": "2.1", "target_ref": "attack-pattern--d10cbd34-42e3-45c0-84d2-535a09849584", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e