VALUES ('doc-09-mitre-attack-p0-9781', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-12T18:05:46.882Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TA2541](https://attack.mitre.org/groups/G1018) has used malicious links to cloud and web services to gain execution on victim machines.(Citation: Proofpoint TA2541 February 2022)(Citation: FireEye NETWIRE March 2019)", "external_references": [{"description": "Larson, S. and Wise, J. (2022, February 15). Charting TA2541''s Flight. Retrieved September 12, 2023.", "source_name": "Proofpoint TA2541 February 2022", "url": "https://www.proofpoint.com/us/blog/threat-insight/charting-ta2541s-flight"}, {"description": "Maniath, S. and Kadam P. (2019, March 19). Dissecting a NETWIRE Phishing Campaign''s Usage of Process Hollowing. Retrieved January 7, 2021.", "source_name": "FireEye NETWIRE March 2019", "url": "https://www.mandiant.com/resources/blog/dissecting-netwire-phishing-campaigns-usage-process-hollowing"}], "id": "relationship--6035f6c6-8e6c-4ac6-9467-722502e90799", "modified": "2026-07-31T18:47:55.293Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--467271fd-47c0-4e90-a3f9-d84f5cf790d0", "spec_version": "2.1", "target_ref": "attack-pattern--ef67e13e-5598-4adc-bdb2-998225874fa9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9781', 0, 106, '09-mitre-attack', 'retrieved', '8EE72C883171958C70543C7EA36FF99EEC3187D72E9B571B70D9978BE3AF5993', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
