VALUES ('doc-09-mitre-attack-p0-9790', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-12T17:58:45.732Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TA2541](https://attack.mitre.org/groups/G1018) has used macro-enabled MS Word documents to lure victims into executing malicious payloads.(Citation: Proofpoint TA2541 February 2022)(Citation: Cisco Operation Layover September 2021)(Citation: Telefonica Snip3 December 2021)\n", "external_references": [{"description": "Jornet, A. (2021, December 23). Snip3, an investigation into malware. Retrieved September 19, 2023.", "source_name": "Telefonica Snip3 December 2021", "url": "https://telefonicatech.com/blog/snip3-investigacion-malware"}, {"description": "Larson, S. and Wise, J. (2022, February 15). Charting TA2541''s Flight. Retrieved September 12, 2023.", "source_name": "Proofpoint TA2541 February 2022", "url": "https://www.proofpoint.com/us/blog/threat-insight/charting-ta2541s-flight"}, {"description": "Ventura, V. (2021, September 16). Operation Layover: How we tracked an attack on the aviation industry to five years of compromise. Retrieved September 15, 2023.", "source_name": "Cisco Operation Layover September 2021", "url": "https://blog.talosintelligence.com/operation-layover-how-we-tracked-attack/"}], "id": "relationship--b0766ea1-924a-4e1f-92db-17e5f4a3b72d", "modified": "2026-07-31T18:47:55.467Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--467271fd-47c0-4e90-a3f9-d84f5cf790d0", "spec_version": "2.1", "target_ref": "attack-pattern--232b7f21-adf9-4b42-b936-b9d6f7df856e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-9790', 0, 136, '09-mitre-attack', 'retrieved', '9050D74753B3777E9EB998CFAB9