VALUES ('doc-09-mitre-attack-p0-10099', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-11-20T18:55:07.885Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sea Turtle](https://attack.mitre.org/groups/G1041) captured legitimate SSL certificates from victim organizations and installed these on [Sea Turtle](https://attack.mitre.org/groups/G1041)-controlled infrastructure to enable subsequent adversary-in-the-middle operations.(Citation: Talos Sea Turtle 2019)", "external_references": [{"description": "Cisco Talos. (2019, April 17). Sea Turtle: DNS Hijacking Abuses Trust In Core Internet Service. Retrieved November 20, 2024.", "source_name": "Talos Sea Turtle 2019", "url": "https://blog.talosintelligence.com/seaturtle/"}], "id": "relationship--44eada28-5194-4661-9ef1-b0a0bfa29af6", "modified": "2026-07-31T18:47:57.467Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--56a05d27-4d47-418a-b330-781c5614f202", "spec_version": "2.1", "target_ref": "attack-pattern--c071d8c1-3b3a-4f22-9407-ca4e96921069", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10099', 0, 82, '09-mitre-attack', 'retrieved', '42D421FE3AE288778CB2DAD73742680EF31D9687098F57D59DD3598CE61B90EA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
