VALUES ('doc-09-mitre-attack-p0-10101', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-11-20T18:50:29.097Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sea Turtle](https://attack.mitre.org/groups/G1041) modified Name Server (NS) items to refer to [Sea Turtle](https://attack.mitre.org/groups/G1041)-controlled DNS servers to provide responses for all DNS lookups.(Citation: Talos Sea Turtle 2019)(Citation: Talos Sea Turtle 2019_2)", "external_references": [{"description": "Cisco Talos. (2019, April 17). Sea Turtle: DNS Hijacking Abuses Trust In Core Internet Service. Retrieved November 20, 2024.", "source_name": "Talos Sea Turtle 2019", "url": "https://blog.talosintelligence.com/seaturtle/"}, {"description": "Paul Rascagneres. (2019, July 9). Sea Turtle keeps on swimming, finds new victims, DNS hijacking techniques. Retrieved November 20, 2024.", "source_name": "Talos Sea Turtle 2019_2", "url": "https://blog.talosintelligence.com/sea-turtle-keeps-on-swimming/"}], "id": "relationship--4dfb2beb-4473-446e-beee-42729d8f87da", "modified": "2026-07-31T18:47:57.518Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--56a05d27-4d47-418a-b330-781c5614f202", "spec_version": "2.1", "target_ref": "attack-pattern--c2f59d25-87fe-44aa-8f83-e8e59d077bf5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10101', 0, 114, '09-mitre-attack', 'retrieved', '03E5455FE279D416C038D6EE226F520143EEB21E7BC2ACC8726356080C5B4305', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
