VALUES ('doc-09-mitre-attack-p0-10103', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-11-20T18:53:29.851Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sea Turtle](https://attack.mitre.org/groups/G1041) created new certificates using a technique called the actors performed \"certificate impersonation,\" a technique in which [Sea Turtle](https://attack.mitre.org/groups/G1041) obtained a certificate authority-signed X.509 certificate from another provider for the same domain imitating the one already used by the targeted organization.(Citation: Talos Sea Turtle 2019)(Citation: Talos Sea Turtle 2019_2)", "external_references": [{"description": "Cisco Talos. (2019, April 17). Sea Turtle: DNS Hijacking Abuses Trust In Core Internet Service. Retrieved November 20, 2024.", "source_name": "Talos Sea Turtle 2019", "url": "https://blog.talosintelligence.com/seaturtle/"}, {"description": "Paul Rascagneres. (2019, July 9). Sea Turtle keeps on swimming, finds new victims, DNS hijacking techniques. Retrieved November 20, 2024.", "source_name": "Talos Sea Turtle 2019_2", "url": "https://blog.talosintelligence.com/sea-turtle-keeps-on-swimming/"}], "id": "relationship--5063d844-fd04-478e-8812-399ba4e7fa58", "modified": "2026-07-31T18:47:57.552Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--56a05d27-4d47-418a-b330-781c5614f202", "spec_version": "2.1", "target_ref": "attack-pattern--19401639-28d0-4c3c-adcc-bc2ba22f6421", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10103', 0, 135, '09-mitre-attack', 'retrieved', '89534ECAFE224080F6D1DDDD49431346F24DD7B04587477CE9619F493991DC6D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "