VALUES ('doc-09-mitre-attack-p0-10120', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-11-20T21:21:01.267Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sea Turtle](https://attack.mitre.org/groups/G1041) connected over TCP using HTTP to establish command and control channels.(Citation: Hunt Sea Turtle 2024)", "external_references": [{"description": "Hunt & Hackett Research Team. (2024, January 5). Turkish espionage campaigns in the Netherlands. Retrieved November 20, 2024.", "source_name": "Hunt Sea Turtle 2024", "url": "https://www.huntandhackett.com/blog/turkish-espionage-campaigns"}], "id": "relationship--eb65138d-8c50-42e3-b0e9-acb49454e22b", "modified": "2026-07-31T18:47:57.910Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--56a05d27-4d47-418a-b330-781c5614f202", "spec_version": "2.1", "target_ref": "attack-pattern--df8b2a25-8bdf-4856-953c-a04372b1c161", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10120', 0, 73, '09-mitre-attack', 'retrieved', '0F96DBBB3E6FA5D3855EF95249E7499CFEDAF25C228F08087C9AFE0E08AE1F2A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
