VALUES ('doc-09-mitre-attack-p0-10122', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-11-20T18:45:03.955Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sea Turtle](https://attack.mitre.org/groups/G1041) modified DNS records at service providers to redirect traffic from legitimate resources to [Sea Turtle](https://attack.mitre.org/groups/G1041)-controlled servers to enable adversary-in-the-middle attacks for credential capture.(Citation: Talos Sea Turtle 2019)(Citation: Talos Sea Turtle 2019_2)", "external_references": [{"description": "Cisco Talos. (2019, April 17). Sea Turtle: DNS Hijacking Abuses Trust In Core Internet Service. Retrieved November 20, 2024.", "source_name": "Talos Sea Turtle 2019", "url": "https://blog.talosintelligence.com/seaturtle/"}, {"description": "Paul Rascagneres. (2019, July 9). Sea Turtle keeps on swimming, finds new victims, DNS hijacking techniques. Retrieved November 20, 2024.", "source_name": "Talos Sea Turtle 2019_2", "url": "https://blog.talosintelligence.com/sea-turtle-keeps-on-swimming/"}], "id": "relationship--f5f42525-f682-400c-ac85-477a7063c4d9", "modified": "2026-07-31T18:47:57.953Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--56a05d27-4d47-418a-b330-781c5614f202", "spec_version": "2.1", "target_ref": "attack-pattern--035bb001-ab69-4a0b-9f6c-2de8b09e1b9d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10122', 0, 118, '09-mitre-attack', 'retrieved', 'BD4DC39BD990976097D147C7E424B726944E5FC580F0E742B7E90E78F5F81DE6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
