VALUES ('doc-09-mitre-attack-p0-10163', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-20T20:22:04.606Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Aquatic Panda](https://attack.mitre.org/groups/G0143) created new Windows services for persistence that masqueraded as legitimate Windows services via name change.(Citation: Crowdstrike HuntReport 2022)", "external_references": [{"description": "CrowdStrike. (2023). 2022 Falcon OverWatch Threat Hunting Report. Retrieved May 20, 2024.", "source_name": "Crowdstrike HuntReport 2022", "url": "https://go.crowdstrike.com/rs/281-OBQ-266/images/2022OverWatchThreatHuntingReport.pdf"}], "id": "relationship--1fbee829-fe84-4a48-a943-5be81abfb43c", "modified": "2026-07-31T18:47:59.196Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--64b52e7d-b2c4-4a02-9372-08a463f5dc11", "spec_version": "2.1", "target_ref": "attack-pattern--2959d63f-73fd-46a1-abd2-109d7dcede32", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10163', 0, 69, '09-mitre-attack', 'retrieved', 'B48AED98C94E35078E234CA20F00031A00834BA4B93A2E582BEAC6327377D7EA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
