INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-10164', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-20T21:22:24.274Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Aquatic Panda](https://attack.mitre.org/groups/G0143) used a registry edit to enable a Windows feature called RestrictedAdmin in victim environments. This change allowed [Aquatic Panda](https://attack.mitre.org/groups/G0143) to leverage \"pass the hash\" mechanisms as the alteration allows for RDP connections with a valid account name and hash only, without possessing a cleartext password value.(Citation: Crowdstrike HuntReport 2022)", "external_references": [{"description": "CrowdStrike. (2023). 2022 Falcon OverWatch Threat Hunting Report. Retrieved May 20, 2024.", "source_name": "Crowdstrike HuntReport 2022", "url": "https://go.crowdstrike.com/rs/281-OBQ-266/images/2022OverWatchThreatHuntingReport.pdf"}], "id": "relationship--245c2bf3-f630-4850-8fef-9580f5672b02", "modified": "2026-07-31T18:47:59.209Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--64b52e7d-b2c4-4a02-9372-08a463f5dc11", "spec_version": "2.1", "target_ref": "attack-pattern--e624264c-033a-424d-9fd7-fc9c3bbdb03e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10164', 0, 100, '09-mitre-attack', 'retrieved', 'D526E970BB585F4AFD9DA70B3A8724DBB1600766035BE9B8AB78601E20165210', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
