VALUES ('doc-09-mitre-attack-p0-10165', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-04-10T18:39:28.849Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Aquatic Panda](https://attack.mitre.org/groups/G0143) has used DLL search-order hijacking to load `exe`, `dll`, and `dat` files into memory.(Citation: CrowdStrike AQUATIC PANDA December 2021) [Aquatic Panda](https://attack.mitre.org/groups/G0143) loaded a malicious DLL into the legitimate Windows Security Health Service executable ( SecurityHealthService.exe ) to execute malicious code on victim systems.(Citation: Crowdstrike HuntReport 2022)", "external_references": [{"description": "CrowdStrike. (2023). 2022 Falcon OverWatch Threat Hunting Report. Retrieved May 20, 2024.", "source_name": "Crowdstrike HuntReport 2022", "url": "https://go.crowdstrike.com/rs/281-OBQ-266/images/2022OverWatchThreatHuntingReport.pdf"}, {"description": "Wiley, B. et al. (2021, December 29). OverWatch Exposes AQUATIC PANDA in Possession of Log4Shell Exploit Tools During Hands-on Intrusion Attempt. Retrieved January 18, 2022.", "source_name": "CrowdStrike AQUATIC PANDA December 2021", "url": "https://www.crowdstrike.com/blog/overwatch-exposes-aquatic-panda-in-possession-of-log-4-shell-exploit-tools/"}], "id": "relationship--38230234-1111-41cf-aa6b-b107577dad61", "modified": "2026-07-31T18:47:59.224Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--64b52e7d-b2c4-4a02-9372-08a463f5dc11", "spec_version": "2.1", "target_ref": "attack-pattern--2fee9321-3e71-4cf4-af24-d4d40d355b34", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10165', 0, 131, '09-mitre-attack', 'retrieved', '5EDBB6B662A552ACEF0C43F018E397C598128F48146E9B96778