VALUES ('doc-09-mitre-attack-p0-10272', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-25T23:08:14.216Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ke3chang](https://attack.mitre.org/groups/G0004) has utilized an ORB (operational relay box) network for reconnaissance and vulnerability exploitation.(Citation: ORB Mandiant)", "external_references": [{"description": "Raggi, Michael. (2024, May 22). IOC Extinction? China-Nexus Cyber Espionage Actors Use ORB Networks to Raise Cost on Defenders. Retrieved July 8, 2024.", "source_name": "ORB Mandiant", "url": "https://cloud.google.com/blog/topics/threat-intelligence/china-nexus-espionage-orb-networks"}], "id": "relationship--d70d3818-39a9-490d-95a4-59fa3a0b313f", "modified": "2026-07-31T18:48:01.802Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--6713ab67-e25b-49cc-808d-2b36d4fbc35c", "spec_version": "2.1", "target_ref": "attack-pattern--31225cd3-cd46-4575-b287-c2c14011c074", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10272', 0, 75, '09-mitre-attack', 'retrieved', 'C93C5B3C3BEEFB76DE9953FEBA60A40D45F6646B526795567567E0B548C92E87', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
