VALUES ('doc-09-mitre-attack-p0-10281', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-25T16:26:37.928Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Saint Bear](https://attack.mitre.org/groups/G1031) has leveraged vulnerabilities in client applications such as CVE-2017-11882 in Microsoft Office to enable code execution in victim environments.(Citation: Palo Alto Unit 42 OutSteel SaintBot February 2022 )", "external_references": [{"description": "Unit 42. (2022, February 25). Spear Phishing Attacks Target Organizations in Ukraine, Payloads Include the Document Stealer OutSteel and the Downloader SaintBot. Retrieved June 9, 2022.", "source_name": "Palo Alto Unit 42 OutSteel SaintBot February 2022 ", "url": "https://unit42.paloaltonetworks.com/ukraine-targeted-outsteel-saintbot/"}], "id": "relationship--0e1a58e9-06e9-4ad5-8445-4068e240e3d7", "modified": "2026-07-31T18:48:00.220Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--674582ec-51c4-42ce-b409-797239e37a2a", "spec_version": "2.1", "target_ref": "attack-pattern--be2dcee9-a7a7-4e38-afd6-21b31ecc3d63", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10281', 0, 99, '09-mitre-attack', 'retrieved', '9A63E9DFA809027BF86EEA47E556B4DAFC994AB19A2E9F561A7FF4E6D308CBFF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
