VALUES ('doc-09-mitre-attack-p0-10282', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-25T16:15:42.454Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[OutSteel](https://attack.mitre.org/software/S1017) is uniquely associated with [Saint Bear](https://attack.mitre.org/groups/G1031) as a post-exploitation document collection and exfiltration tool.(Citation: Palo Alto Unit 42 OutSteel SaintBot February 2022 )", "external_references": [{"description": "Unit 42. (2022, February 25). Spear Phishing Attacks Target Organizations in Ukraine, Payloads Include the Document Stealer OutSteel and the Downloader SaintBot. Retrieved June 9, 2022.", "source_name": "Palo Alto Unit 42 OutSteel SaintBot February 2022 ", "url": "https://unit42.paloaltonetworks.com/ukraine-targeted-outsteel-saintbot/"}], "id": "relationship--1238411a-1012-470d-af86-8bad2e3e709c", "modified": "2026-07-31T18:48:00.241Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--674582ec-51c4-42ce-b409-797239e37a2a", "spec_version": "2.1", "target_ref": "malware--c113230f-f044-423b-af63-9b63c802f5ae", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10282', 0, 93, '09-mitre-attack', 'retrieved', '77F840BC002A507418E92E05FA5AE598ABC3C0FF4E2E61C8773013804C0DD34B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
