VALUES ('doc-09-mitre-attack-p0-10291', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-25T16:38:50.377Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Saint Bear](https://attack.mitre.org/groups/G1031) has impersonated government and related entities in both phishing activity and developing web sites with malicious links that mimic legitimate resources.(Citation: Cadet Blizzard emerges as novel threat actor)", "external_references": [{"description": "Microsoft Threat Intelligence. (2023, June 14). Cadet Blizzard emerges as a novel and distinct Russian threat actor. Retrieved July 10, 2023.", "source_name": "Cadet Blizzard emerges as novel threat actor", "url": "https://www.microsoft.com/en-us/security/blog/2023/06/14/cadet-blizzard-emerges-as-a-novel-and-distinct-russian-threat-actor/"}], "id": "relationship--61035d89-bac7-4267-829f-a898eeb41f11", "modified": "2026-07-31T18:48:00.359Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--674582ec-51c4-42ce-b409-797239e37a2a", "spec_version": "2.1", "target_ref": "attack-pattern--cd92d2b8-ce43-4666-9472-f1b4b9f4f8be", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10291', 0, 92, '09-mitre-attack', 'retrieved', '38D6B5AF30D605900D5994204A8DA11BD89D59E972CC4085A95197BDCD1F9ECA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
