VALUES ('doc-09-mitre-attack-p0-10345', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-10-10T22:19:43.951Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DarkHydrus](https://attack.mitre.org/groups/G0079) has used -WindowStyle Hidden to conceal [PowerShell](https://attack.mitre.org/techniques/T1059/001) windows. (Citation: Unit 42 DarkHydrus July 2018)", "external_references": [{"description": "Falcone, R., et al. (2018, July 27). New Threat Actor Group DarkHydrus Targets Middle East Government. Retrieved August 2, 2018.", "source_name": "Unit 42 DarkHydrus July 2018", "url": "https://researchcenter.paloaltonetworks.com/2018/07/unit42-new-threat-actor-group-darkhydrus-targets-middle-east-government/"}], "id": "relationship--ab3cf933-236f-4255-9ca6-24826f9bbe99", "modified": "2026-07-31T20:48:37.200Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--6b9ebeb5-20bf-48b0-afb7-988d769a2f01", "spec_version": "2.1", "target_ref": "attack-pattern--cbb66055-0325-4111-aca0-40547b6ad5b0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10345', 0, 74, '09-mitre-attack', 'retrieved', '3D28157DDBDFA490F1E8E1A00BD7C8B83343F6943CC60144BF6E253C61D7FC39', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
