VALUES ('doc-09-mitre-attack-p0-10348', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DarkHydrus](https://attack.mitre.org/groups/G0079) used an open-source tool, Phishery, to inject malicious remote template URLs into Microsoft Word documents and then sent them to victims to enable [Forced Authentication](https://attack.mitre.org/techniques/T1187).(Citation: Unit 42 Phishery Aug 2018)", "external_references": [{"description": "Falcone, R. (2018, August 07). DarkHydrus Uses Phishery to Harvest Credentials in the Middle East. Retrieved August 10, 2018.", "source_name": "Unit 42 Phishery Aug 2018", "url": "https://researchcenter.paloaltonetworks.com/2018/08/unit42-darkhydrus-uses-phishery-harvest-credentials-middle-east/"}], "id": "relationship--e3a3186e-2ce7-4d46-836e-dc024464ede7", "modified": "2026-07-31T20:48:37.226Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--6b9ebeb5-20bf-48b0-afb7-988d769a2f01", "spec_version": "2.1", "target_ref": "attack-pattern--dc31fe1e-d722-49da-8f5f-92c7b5aff534", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-10348', 0, 89, '09-mitre-attack', 'retrieved', 'E36B1992DF7F3A89189852ADCF529177E3613F7D0D901EF62BED9AD9EB571D4D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
